import re

from robot.api import logger

from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.utils.converters import create_dict_with_key, create_dict
from ta_egate_cmd_parser.utils.values_parsers import parse_throughput


class UeStatsFailure(Exception):
    """
    Exception class for ue_stats
    """
    pass


class UeStats(EgateCommandBase):
    """
    Parser for ue_stats command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(UeStats, self).__init__()
        self.command = 'ue_stats'
        self.params = params
        self.executed_phrase = r'.*?UE\-\d+.*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        self.parsers = {
            'pcell_only': {
                'dl_mac': self._parse_with_pcell_only_and_ue_id_and_type_dl_mac,
                'ul_mac': self._parse_with_pcell_only_and_ue_id_and_type_ul_mac
            },
            'pcell_and_scell': {
                'dl_mac': self._parse_with_pcell_and_scells_and_ue_id_and_type_dl_mac,
                'ul_mac': self._parse_with_pcell_only_and_ue_id_and_type_ul_mac,
                'pdsch': self._parse_with_pcell_and_scells_and_ue_id_and_type_pdsch,
                'pusch': self._parse_with_pcell_and_scells_and_ue_id_and_type_pusch
            }
        }
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute(self, egate_id=0):
        """
        Execute ue_stats command.
        :return: command status and output
        """
        status, output = super(UeStats, self).execute(egate_id=egate_id, command=self.to_execute, fail_regexp=self.fail_regexp)
        if status:
            return status, output
        else:
            raise UeStatsFailure(output)

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return: parsed output
        """
        status, output = super(UeStats, self).execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_ue_stats_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise UeStatsFailure(output)

    def _build_command(self):
        """
        Build ue_stats command.
        :return: None
        """
        for param, value in list(self.params.items()):
            if param in ["display", "clear", "check"]:
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def _parse_ue_stats_output(self, output):
        if 'scell' not in list(self.params.keys()):
            return self.parsers['pcell_only'][self.params['type']](output)
        else:
            return self.parsers['pcell_and_scell'][self.params['type']](output)

    def _parse_with_pcell_only_and_ue_id_and_type_dl_mac(self, cmd_output):
        """
        Parse ue_stats command output.
        :param cmd_output: output received from execution of ue_stats command
        e.g.:

        UE-1: DL MAC PDU Throughput
        ========================================================
        SCell       Current    Minimum    Maximum    Average
        --------------------------------------------------------
        PCell       10.1 Mbps  10.1 Mbps  10.1 Mbps  10.1 Mbps
        Aggregated  10.1 Mbps  10.1 Mbps  10.1 Mbps  10.1 Mbps
        ========================================================

        EGATE>

        :return: dict containing values of avg, min, max and last throughput
        e.g.:
        { 'PCell': {
                    'Current': {'unit': 'Mbps', 'value': '10.1'},
                    'Average': {'unit': 'Mbps', 'value': '10.1'},
                    'Minimum': {'unit': 'Mbps', 'value': '10.1'},
                    'Maximum': {'unit': 'Mbps', 'value': '10.1'},
                    'SCell': 'PCell'},
          'Aggregated': {
                    'Current': {'unit': 'Mbps', 'value': '10.1'},
                    'Average': {'unit': 'Mbps', 'value': '10.1'},
                    'Minimum': {'unit': 'Mbps', 'value': '10.1'},
                    'Maximum': {'unit': 'Mbps', 'value': '10.1'},
                    'SCell': 'Aggregated'}}
        """
        if re.findall(r'Error:.*', str(cmd_output)):
            raise UeStatsFailure(re.findall(r'Error:.*', str(cmd_output))[0])
        else:
            cmd_parser = EgateDispCommandsOutputParser(cmd_output)
            cmd_parser.parse_column_value_with_custom_function('Current', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Average', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Minimum', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Maximum', parse_throughput)
            output = cmd_parser.get_list_of_output_parsed_lines()
            return create_dict_with_key(key='SCell',
                                        list_of_output_parsed_lines=output)

    def _parse_with_pcell_and_scells_and_ue_id_and_type_dl_mac(self, cmd_output):
        """
        Parse ue_stats command output.
        :param cmd_output: output received from execution of ue_stats command

        e.g.:

        EGATE> ue_stats id=70 type=dl_mac scell=0,1,2,3

        UE-70: DL MAC PDU Throughput for all UEs cells
        ========================================================
        SCell       Current    Minimum    Maximum    Average
        --------------------------------------------------------
        PCell       36.2 Mbps  36.1 Mbps  36.2 Mbps  36.2 Mbps
        SCell-1     14.1 Mbps  14.1 Mbps  14.1 Mbps  14.1 Mbps
        SCell-2     0          0          0          0
        SCell-3     0          0          0          0
        Aggregated  50.2 Mbps  50.2 Mbps  50.2 Mbps  50.2 Mbps
        ========================================================

        EGATE>

        :return:

        """
        if re.findall(r'Error:.*', str(cmd_output)):
            raise UeStatsFailure(re.findall(r'Error:.*', str(cmd_output))[0])
        else:
            cmd_parser = EgateDispCommandsOutputParser(cmd_output)
            cmd_parser.parse_column_value_with_custom_function('Current', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Average', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Minimum', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Maximum', parse_throughput)
            output = cmd_parser.get_list_of_output_parsed_lines()

            return create_dict_with_key(key='SCell', list_of_output_parsed_lines=output)

    def _parse_with_pcell_only_and_ue_id_and_type_ul_mac(self, cmd_output):
        """
        Parse ue_stats command output.
        :param cmd_output: output received from execution of ue_stats command
        e.g.:

        UE-1: UL MAC PDU Throughput
        ========================================
        Current   Minimum   Maximum   Average
        ----------------------------------------
        1.0 Mbps  1.0 Mbps  1.0 Mbps  1.0 Mbps
        ========================================

        UE-1: UL MAC Last BSR Statistics
        ========================
        Parameter        Value
        ------------------------
        BSR type         LONG
        LCG0: BSR index  0
        LCG1: BSR index  0
        LCG2: BSR index  0
        LCG3: BSR index  0
        ========================
        :return: dict containing values of avg, min, max and last throughput
        e.g.:

        {
          'Current': [{'unit': 'Mbps', 'value': '1.0'}],
          'Average': [{'unit': 'Mbps', 'value': '1.0'}],
          'Minimum':  [{'unit': 'Mbps', 'value': '1.0'}],
          'Maximum': [{'unit': 'Mbps', 'value': '1.0'}]
        }

        """
        if re.findall(r'Error:.*', str(cmd_output)):
            raise UeStatsFailure(re.findall(r'Error:.*', str(cmd_output))[0])
        else:
            cmd_parser = EgateDispCommandsOutputParser(cmd_output)
            cmd_parser.parse_column_value_with_custom_function('Current', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Average', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Minimum', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Maximum', parse_throughput)
            output = cmd_parser.get_list_of_output_parsed_lines()
            return create_dict(list_of_output_parsed_lines=output)

